/**
 * AiProviderCard tests.
 *
 * Covers:
 *   - Configured state → success status pill + masked (••••••••) field placeholder.
 *   - Not-configured state → neutral status pill, empty placeholder.
 *   - Empty submit calls onSave("") so the stored key is preserved.
 *   - Typed submit passes the entered value to onSave.
 *   - Save button is disabled while a save is in flight.
 *   - a11y: the key input is labelled, the Save button has an accessible name.
 */

import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import { AiProviderCard } from "../../src/components/AiProviderCard";
import { ProviderKeyError, type ProviderKey } from "../../src/api/providerKeys";

function key(overrides: Partial<ProviderKey> = {}): ProviderKey {
  return {
    provider: "serper",
    configured: true,
    updated_at: "2026-08-21T10:00:00Z",
    updated_by: "user-1",
    updated_by_name: "Ada Admin",
    ...overrides,
  };
}

describe("AiProviderCard", () => {
  it("shows a Configured status pill and a masked field when configured", () => {
    render(
      <AiProviderCard
        providerKey={key({ configured: true })}
        displayName="Serper"
        brandColor="#5b6ef5"
        onSave={vi.fn(async () => {})}
      />,
    );

    expect(
      screen.getByText(m.admin_integrations_providers_configured()),
    ).toBeInTheDocument();
    const input = screen.getByLabelText(
      m.admin_integrations_providers_key_label(),
    ) as HTMLInputElement;
    expect(input.type).toBe("password");
    expect(input.placeholder).toBe("••••••••");
  });

  it("shows a Not configured status pill and empty placeholder when unconfigured", () => {
    render(
      <AiProviderCard
        providerKey={key({ configured: false })}
        displayName="Apify"
        brandColor="#ff9900"
        onSave={vi.fn(async () => {})}
      />,
    );

    expect(
      screen.getByText(m.admin_integrations_providers_not_configured()),
    ).toBeInTheDocument();
    const input = screen.getByLabelText(
      m.admin_integrations_providers_key_label(),
    ) as HTMLInputElement;
    expect(input.placeholder).toBe("");
  });

  it("calls onSave with an empty string when submitting a blank field (preserve)", async () => {
    const onSave = vi.fn(async () => {});
    const user = userEvent.setup();
    render(
      <AiProviderCard
        providerKey={key({ configured: true })}
        displayName="Serper"
        brandColor="#5b6ef5"
        onSave={onSave}
      />,
    );

    await user.click(
      screen.getByRole("button", { name: m.admin_integrations_providers_save_btn() }),
    );
    await waitFor(() => expect(onSave).toHaveBeenCalledWith(""));
  });

  it("sends \"\" (not whitespace) when a configured provider's field holds only a space (preserve)", async () => {
    // Regression: typing a single space into an already-configured provider and
    // saving must NOT send " " (which the server writes into Vault as a real
    // key, destroying the working one). Whitespace-only is treated as empty →
    // onSave(""), i.e. "keep the stored key".
    const onSave = vi.fn(async () => {});
    const user = userEvent.setup();
    render(
      <AiProviderCard
        providerKey={key({ configured: true })}
        displayName="Serper"
        brandColor="#5b6ef5"
        onSave={onSave}
      />,
    );

    const input = screen.getByLabelText(
      m.admin_integrations_providers_key_label(),
    ) as HTMLInputElement;
    await user.type(input, " ");
    expect(input.value).toBe(" ");
    await user.click(
      screen.getByRole("button", {
        name: m.admin_integrations_providers_save_btn(),
      }),
    );
    await waitFor(() => expect(onSave).toHaveBeenCalledWith(""));
    expect(onSave).not.toHaveBeenCalledWith(" ");
  });

  it("passes the typed value to onSave", async () => {
    const onSave = vi.fn(async () => {});
    const user = userEvent.setup();
    render(
      <AiProviderCard
        providerKey={key({ configured: false })}
        displayName="Jina"
        brandColor="#000000"
        onSave={onSave}
      />,
    );

    await user.type(
      screen.getByLabelText(m.admin_integrations_providers_key_label()),
      "sk-jina-xyz",
    );
    await user.click(
      screen.getByRole("button", { name: m.admin_integrations_providers_save_btn() }),
    );
    await waitFor(() => expect(onSave).toHaveBeenCalledWith("sk-jina-xyz"));
  });

  it("clears the field back to the masked state after a successful save", async () => {
    const onSave = vi.fn(async () => {});
    const user = userEvent.setup();
    render(
      <AiProviderCard
        providerKey={key({ configured: true })}
        displayName="Serper"
        brandColor="#5b6ef5"
        onSave={onSave}
      />,
    );

    const input = screen.getByLabelText(
      m.admin_integrations_providers_key_label(),
    ) as HTMLInputElement;
    await user.type(input, "sk-new");
    expect(input.value).toBe("sk-new");
    await user.click(
      screen.getByRole("button", { name: m.admin_integrations_providers_save_btn() }),
    );
    await waitFor(() => expect(input.value).toBe(""));
  });

  it("disables the Save button while a save is in flight", async () => {
    let resolve!: () => void;
    const onSave = vi.fn(
      () =>
        new Promise<void>((r) => {
          resolve = r;
        }),
    );
    const user = userEvent.setup();
    render(
      <AiProviderCard
        providerKey={key({ configured: true })}
        displayName="Serper"
        brandColor="#5b6ef5"
        onSave={onSave}
      />,
    );

    // Configured provider: an empty submit is intentional (keep the stored
    // key), so Save is enabled before and after — isolating the in-flight
    // disable toggle from the no-op disable rule.
    const btn = screen.getByRole("button", {
      name: m.admin_integrations_providers_save_btn(),
    });
    await user.click(btn);
    await waitFor(() => expect(btn).toBeDisabled());
    resolve();
    await waitFor(() => expect(btn).not.toBeDisabled());
  });

  it("shows the role-denied alert and retains input + re-enables Save on a 403", async () => {
    const onSave = vi.fn(async () => {
      throw new ProviderKeyError(403, "setProviderKey failed: 403 — nope");
    });
    const user = userEvent.setup();
    render(
      <AiProviderCard
        providerKey={key({ configured: false })}
        displayName="Serper"
        brandColor="#5b6ef5"
        onSave={onSave}
      />,
    );

    const input = screen.getByLabelText(
      m.admin_integrations_providers_key_label(),
    ) as HTMLInputElement;
    await user.type(input, "sk-denied");
    const btn = screen.getByRole("button", {
      name: m.admin_integrations_providers_save_btn(),
    });
    await user.click(btn);

    const alert = await screen.findByRole("alert");
    expect(alert).toHaveTextContent(
      m.admin_integrations_providers_role_denied(),
    );
    // The typed value is retained (not cleared) so the admin can retry.
    expect(input.value).toBe("sk-denied");
    // Save is re-enabled, not stuck disabled.
    expect(btn).not.toBeDisabled();
  });

  it("shows the generic save-error message when onSave rejects with a plain Error", async () => {
    const onSave = vi.fn(async () => {
      throw new Error("network down");
    });
    const user = userEvent.setup();
    render(
      <AiProviderCard
        providerKey={key({ configured: false })}
        displayName="Serper"
        brandColor="#5b6ef5"
        onSave={onSave}
      />,
    );

    await user.type(
      screen.getByLabelText(m.admin_integrations_providers_key_label()),
      "sk-fail",
    );
    await user.click(
      screen.getByRole("button", {
        name: m.admin_integrations_providers_save_btn(),
      }),
    );

    const alert = await screen.findByRole("alert");
    expect(alert).toHaveTextContent(
      m.admin_integrations_providers_save_error(),
    );
  });

  it("uses the generic save-error message for a non-403 ProviderKeyError", async () => {
    const onSave = vi.fn(async () => {
      throw new ProviderKeyError(500, "setProviderKey failed: 500");
    });
    const user = userEvent.setup();
    render(
      <AiProviderCard
        providerKey={key({ configured: false })}
        displayName="Serper"
        brandColor="#5b6ef5"
        onSave={onSave}
      />,
    );

    await user.type(
      screen.getByLabelText(m.admin_integrations_providers_key_label()),
      "sk-500",
    );
    await user.click(
      screen.getByRole("button", {
        name: m.admin_integrations_providers_save_btn(),
      }),
    );

    const alert = await screen.findByRole("alert");
    expect(alert).toHaveTextContent(
      m.admin_integrations_providers_save_error(),
    );
    expect(alert).not.toHaveTextContent(
      m.admin_integrations_providers_role_denied(),
    );
  });

  it("ties the stored-key hint to the input via aria-describedby when configured", () => {
    render(
      <AiProviderCard
        providerKey={key({ configured: true })}
        displayName="Serper"
        brandColor="#5b6ef5"
        onSave={vi.fn(async () => {})}
      />,
    );

    const input = screen.getByLabelText(
      m.admin_integrations_providers_key_label(),
    );
    const describedBy = input.getAttribute("aria-describedby");
    expect(describedBy).toBeTruthy();
    const hint = document.getElementById(describedBy as string);
    expect(hint).toHaveTextContent(
      m.admin_integrations_providers_key_stored_hint(),
    );
  });

  it("has no aria-describedby when not configured (no hint present)", () => {
    render(
      <AiProviderCard
        providerKey={key({ configured: false })}
        displayName="Serper"
        brandColor="#5b6ef5"
        onSave={vi.fn(async () => {})}
      />,
    );

    const input = screen.getByLabelText(
      m.admin_integrations_providers_key_label(),
    );
    expect(input).not.toHaveAttribute("aria-describedby");
  });

  it("disables Save for a no-op (not configured + empty field) and enables it on typing", async () => {
    const user = userEvent.setup();
    render(
      <AiProviderCard
        providerKey={key({ configured: false })}
        displayName="Serper"
        brandColor="#5b6ef5"
        onSave={vi.fn(async () => {})}
      />,
    );

    const btn = screen.getByRole("button", {
      name: m.admin_integrations_providers_save_btn(),
    });
    expect(btn).toBeDisabled();

    await user.type(
      screen.getByLabelText(m.admin_integrations_providers_key_label()),
      "sk-typed",
    );
    expect(btn).not.toBeDisabled();
  });

  it("clears a stale success banner when the user edits the field", async () => {
    const onSave = vi.fn(async () => {});
    const user = userEvent.setup();
    render(
      <AiProviderCard
        providerKey={key({ configured: true })}
        displayName="Serper"
        brandColor="#5b6ef5"
        onSave={onSave}
      />,
    );

    await user.click(
      screen.getByRole("button", {
        name: m.admin_integrations_providers_save_btn(),
      }),
    );
    const success = await screen.findByRole("status");
    expect(success).toHaveTextContent(
      m.admin_integrations_providers_save_success(),
    );

    await user.type(
      screen.getByLabelText(m.admin_integrations_providers_key_label()),
      "x",
    );
    await waitFor(() =>
      expect(screen.queryByRole("status")).not.toBeInTheDocument(),
    );
  });

  it("names the provider via an accessible heading", () => {
    render(
      <AiProviderCard
        providerKey={key({ configured: true })}
        displayName="Serper"
        brandColor="#5b6ef5"
        onSave={vi.fn(async () => {})}
      />,
    );
    expect(
      screen.getByRole("heading", { name: "Serper" }),
    ).toBeInTheDocument();
  });
});


--- frontends/admin-mfe/tests/components/AiProvidersSection.test.tsx (158 lines) ---
/**
 * AiProvidersSection tests.
 *
 * Covers:
 *   - Loads via listProviderKeys and renders the "AI providers" heading plus
 *     a card for each of the three providers (Serper, Apify, Jina).
 *   - Reflects per-provider configured/not-configured state from the fetch.
 *   - Save round-trip: setProviderKey is called with the provider slug + key,
 *     and on success the card's field re-masks.
 *   - 403 on load → a platform-admin-only message (branched on status).
 *   - Non-403 load failure → a generic load-error message.
 */

import { render, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi, beforeEach } from "vitest";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import type { ProviderKey } from "../../src/api/providerKeys";
import { ProviderKeyError } from "../../src/api/providerKeys";

// Mock the API seam so the section's data fetch is deterministic.
vi.mock("../../src/api/providerKeys", async (importOriginal) => {
  const actual = await importOriginal<typeof import("../../src/api/providerKeys")>();
  return {
    ...actual,
    listProviderKeys: vi.fn(),
    setProviderKey: vi.fn(),
  };
});

import {
  listProviderKeys,
  setProviderKey,
} from "../../src/api/providerKeys";
import { AiProvidersSection } from "../../src/components/AiProvidersSection";

const mockList = vi.mocked(listProviderKeys);
const mockSet = vi.mocked(setProviderKey);

function key(provider: string, configured: boolean): ProviderKey {
  return {
    provider,
    configured,
    updated_at: configured ? "2026-08-21T10:00:00Z" : null,
    updated_by: configured ? "user-1" : "",
    updated_by_name: configured ? "Ada Admin" : "",
  };
}

beforeEach(() => {
  vi.clearAllMocks();
});

describe("AiProvidersSection", () => {
  it("renders the section heading and a card per provider after load", async () => {
    mockList.mockResolvedValue([
      key("serper", true),
      key("apify", false),
      key("jina", true),
    ]);

    render(<AiProvidersSection />);

    expect(
      await screen.findByRole("heading", {
        name: m.admin_integrations_providers_section_heading(),
      }),
    ).toBeInTheDocument();

    expect(screen.getByRole("heading", { name: "Serper" })).toBeInTheDocument();
    expect(screen.getByRole("heading", { name: "Apify" })).toBeInTheDocument();
    expect(screen.getByRole("heading", { name: "Jina" })).toBeInTheDocument();

    // apify was not configured → shows the Not configured pill
    const apifyCard = screen.getByTestId("ai-provider-card-apify");
    expect(
      within(apifyCard).getByText(
        m.admin_integrations_providers_not_configured(),
      ),
    ).toBeInTheDocument();
  });

  it("renders all three cards even when the API returns an empty array", async () => {
    mockList.mockResolvedValue([]);

    render(<AiProvidersSection />);

    await screen.findByRole("heading", { name: "Serper" });
    // absent providers default to not-configured
    const serperCard = screen.getByTestId("ai-provider-card-serper");
    expect(
      within(serperCard).getByText(
        m.admin_integrations_providers_not_configured(),
      ),
    ).toBeInTheDocument();
  });

  it("saves a key via setProviderKey and re-masks the field on success", async () => {
    mockList.mockResolvedValue([
      key("serper", false),
      key("apify", false),
      key("jina", false),
    ]);
    mockSet.mockResolvedValue(key("serper", true));

    const user = userEvent.setup();
    render(<AiProvidersSection />);

    await screen.findByRole("heading", { name: "Serper" });
    const serperCard = screen.getByTestId("ai-provider-card-serper");
    const input = within(serperCard).getByLabelText(
      m.admin_integrations_providers_key_label(),
    ) as HTMLInputElement;

    await user.type(input, "sk-serper-99");
    await user.click(
      within(serperCard).getByRole("button", {
        name: m.admin_integrations_providers_save_btn(),
      }),
    );

    await waitFor(() =>
      expect(mockSet).toHaveBeenCalledWith("serper", "sk-serper-99"),
    );
    // field clears back to the masked state after success
    await waitFor(() => expect(input.value).toBe(""));
    // and the provider now reads as configured
    await waitFor(() =>
      expect(
        within(serperCard).getByText(
          m.admin_integrations_providers_configured(),
        ),
      ).toBeInTheDocument(),
    );
  });

  it("shows a platform-admin-only message when the load returns 403", async () => {
    mockList.mockRejectedValue(new ProviderKeyError(403, "forbidden"));

    render(<AiProvidersSection />);

    expect(
      await screen.findByText(m.admin_integrations_providers_role_denied()),
    ).toBeInTheDocument();
  });

  it("shows a generic load-error message on a non-403 failure", async () => {
    mockList.mockRejectedValue(new ProviderKeyError(500, "boom"));

    render(<AiProvidersSection />);

    expect(
      await screen.findByText(m.admin_integrations_providers_load_error()),
    ).toBeInTheDocument();
  });
});


--- frontends/admin-mfe/tests/components/EmailIntegrationCard.test.tsx (553 lines) ---
// Tests for EmailIntegrationCard.
//
// Covers:
//   - Empty state (GET returns present:false) renders defaults, no
//     "password is stored" hints.
//   - Loaded state (GET returns a populated row) pre-fills fields and
//     surfaces the "password is stored" hints for both passwords.
//   - PATCH submits only what the user typed; empty passwords stay
//     empty so the server preserves the existing Vault ref.
//   - 403 from upstream surfaces the role-denied translation.

import { render, screen, waitFor, fireEvent, act } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi, beforeEach, afterEach } from "vitest";
import type { MockInstance } from "vitest";

import { EmailIntegrationCard } from "../../src/components/EmailIntegrationCard";

function jsonResp(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

let fetchSpy: MockInstance<typeof fetch>;

beforeEach(() => {
  fetchSpy = vi.spyOn(globalThis, "fetch");
});
afterEach(() => {
  fetchSpy.mockRestore();
});

describe("EmailIntegrationCard", () => {
  it("renders defaults when GET returns present:false (no row yet)", async () => {
    fetchSpy.mockImplementation(async (input) => {
      const url = typeof input === "string" ? input : input.toString();
      if (url.includes("/api/v1/admin/integrations/email")) {
        return jsonResp(200, { data: { present: false } });
      }
      return jsonResp(404, {});
    });

    render(<EmailIntegrationCard />);

    // Wait for the loading state to clear.
    await waitFor(() => {
      expect(screen.getByTestId("email-integration-form")).toBeInTheDocument();
    });

    // Smoke: the form rendered with the default ports filled in.
    const port = screen.getByLabelText(/port/i, { selector: "#smtp-port" }) as HTMLInputElement;
    expect(port.value).toBe("587");
  });

  it("renders 'password is stored' hint when GET returns Vault path refs", async () => {
    fetchSpy.mockImplementation(async (input) => {
      const url = typeof input === "string" ? input : input.toString();
      if (url.includes("/api/v1/admin/integrations/email")) {
        return jsonResp(200, {
          data: {
            present: true,
            integration: {
              org_id: "abc",
              smtp_host: "smtp.example.com",
              smtp_port: 465,
              smtp_username: "admin@example.com",
              smtp_use_tls: true,
              smtp_from_address: "no-reply@example.com",
              smtp_password_vault_path: "org/abc/email",
              imap_host: "imap.example.com",
              imap_port: 993,
              imap_username: "admin@example.com",
              imap_use_ssl: true,
              imap_folder: "INBOX",
              imap_password_vault_path: "org/abc/email",
              updated_by: "user-1",
            },
          },
        });
      }
      return jsonResp(404, {});
    });

    render(<EmailIntegrationCard />);

    await waitFor(() => {
      expect(screen.getByTestId("email-integration-form")).toBeInTheDocument();
    });

    const smtpHost = screen.getByLabelText(/host/i, { selector: "#smtp-host" }) as HTMLInputElement;
    expect(smtpHost.value).toBe("smtp.example.com");

    // The "password is stored" hint should appear under BOTH password
    // inputs because both Vault refs are non-empty.
    const hints = screen.getAllByText(/password is stored/i);
    expect(hints.length).toBe(2);
  });

  it("PATCH submits with empty password when user doesn't type one", async () => {
    let patchBody: unknown = null;
    fetchSpy.mockImplementation(async (input, init) => {
      const url = typeof input === "string" ? input : input.toString();
      const method = init?.method ?? "GET";
      if (method === "GET" && url.includes("/integrations/email")) {
        return jsonResp(200, { data: { present: false } });
      }
      if (method === "PATCH" && url.includes("/integrations/email")) {
        patchBody = JSON.parse(init?.body as string);
        return jsonResp(200, {
          data: {
            present: true,
            integration: { org_id: "abc", smtp_host: "smtp.new.example", smtp_port: 587, smtp_username: "", smtp_use_tls: true, smtp_from_address: "", smtp_password_vault_path: "", imap_host: "", imap_port: 993, imap_username: "", imap_use_ssl: true, imap_folder: "INBOX", imap_password_vault_path: "", updated_by: "u" },
          },
        });
      }
      return jsonResp(404, {});
    });

    render(<EmailIntegrationCard />);
    await waitFor(() => expect(screen.getByTestId("email-integration-form")).toBeInTheDocument());

    const host = screen.getByLabelText(/host/i, { selector: "#smtp-host" }) as HTMLInputElement;
    fireEvent.change(host, { target: { value: "smtp.new.example" } });

    await act(async () => {
      fireEvent.click(screen.getByTestId("email-integration-save"));
    });

    await waitFor(() => {
      expect(screen.getByTestId("email-integration-success")).toBeInTheDocument();
    });

    const body = patchBody as { smtp_host: string; smtp_password: string };
    expect(body.smtp_host).toBe("smtp.new.example");
    expect(body.smtp_password).toBe("");
  });

  it("surfaces role-denied translation on 403", async () => {
    fetchSpy.mockImplementation(async (input, init) => {
      const url = typeof input === "string" ? input : input.toString();
      const method = init?.method ?? "GET";
      if (method === "GET" && url.includes("/integrations/email")) {
        return jsonResp(200, { data: { present: false } });
      }
      if (method === "PATCH" && url.includes("/integrations/email")) {
        return jsonResp(403, { error: { message: "OWNER or ADMIN required" } });
      }
      return jsonResp(404, {});
    });

    render(<EmailIntegrationCard />);
    await waitFor(() => expect(screen.getByTestId("email-integration-form")).toBeInTheDocument());

    await act(async () => {
      fireEvent.click(screen.getByTestId("email-integration-save"));
    });

    await waitFor(() => {
      const err = screen.getByTestId("email-integration-error");
      expect(err.textContent).toMatch(/owner|admin/i);
    });
  });

  it("surfaces role-denied translation on 403 even when the message has no OWNER/ADMIN substring", async () => {
    // Guards against string-sniffing regressions: the role-denied branch
    // must key off the structured HTTP status the API layer attaches to
    // its thrown error, not `msg.includes("403")` / "OWNER" / "ADMIN" —
    // a brittle substring check that silently stops matching the moment
    // the BFF's error copy changes.
    fetchSpy.mockImplementation(async (input, init) => {
      const url = typeof input === "string" ? input : input.toString();
