/**
 * Modal — dismiss-guard handler tests.
 *
 * The real Radix DismissableLayer does not reliably drive its
 * onPointerDownOutside / onInteractOutside / onEscapeKeyDown callbacks under
 * jsdom (it applies pointer-events:none to the page and constructs synthetic
 * outside events that fireEvent/user-event cannot faithfully reproduce). So we
 * stub the shared `Dialog` primitive with a lightweight test double that
 * captures the handler props Modal wires onto Dialog.Content, then invoke them
 * directly to assert Modal's `dismissible` gate (Modal.tsx:81-104):
 *   - dismissible=true  → handlers do NOT preventDefault
 *   - dismissible=false → handlers DO preventDefault
 * This is the "mock the dependency, not the component under test" pattern.
 */

import { render } from "@testing-library/react";
import { describe, it, expect, vi, beforeEach } from "vitest";
import type { ReactNode } from "react";
import type { TranslatedString } from "@omnicore-platform/platform-chrome";

// Capture the props Modal passes to Dialog.Content so each test can invoke the
// guard handlers directly.
interface CapturedContentProps {
  onEscapeKeyDown?: (e: { preventDefault: () => void }) => void;
  onPointerDownOutside?: (e: { preventDefault: () => void }) => void;
  onInteractOutside?: (e: { preventDefault: () => void }) => void;
  onOpenAutoFocus?: (e: { preventDefault: () => void; currentTarget: unknown }) => void;
  closeLabel?: string;
  role?: string;
}

let captured: CapturedContentProps = {};

vi.mock("@omnicore-platform/ui", () => ({
  Dialog: {
    Root: ({ children }: { children: ReactNode }) => <div>{children}</div>,
    Content: (props: CapturedContentProps & { children?: ReactNode }) => {
      const { children, ...rest } = props;
      captured = rest;
      return <div data-testid="stub-content">{children}</div>;
    },
    Title: ({ children }: { children: ReactNode }) => <h2>{children}</h2>,
    Description: ({ children }: { children: ReactNode }) => <p>{children}</p>,
    Trigger: ({ children }: { children: ReactNode }) => <>{children}</>,
  },
}));

import { Modal } from "../../src/components/Modal";

function ts(s: string): TranslatedString {
  return s as unknown as TranslatedString;
}

// Filler child text routed through a const — react/jsx-no-literals (noStrings)
// forbids inline JSX string literals.
const CONTENT = "content";

function makeEvent(): { preventDefault: () => void; prevented: boolean } {
  const e = {
    prevented: false,
    preventDefault() {
      e.prevented = true;
    },
  };
  return e;
}

describe("Modal — dismiss guards (dismissible gate)", () => {
  beforeEach(() => {
    captured = {};
  });

  it("does NOT preventDefault on Esc / outside handlers when dismissible (default)", () => {
    render(
      <Modal title={ts("Dismissible")} open onClose={vi.fn()}>
        <span>{CONTENT}</span>
      </Modal>,
    );

    const esc = makeEvent();
    captured.onEscapeKeyDown?.(esc);
    expect(esc.prevented).toBe(false);

    const pd = makeEvent();
    captured.onPointerDownOutside?.(pd);
    expect(pd.prevented).toBe(false);

    const io = makeEvent();
    captured.onInteractOutside?.(io);
    expect(io.prevented).toBe(false);

    // dismissible=true wires a built-in close button (closeLabel set).
    expect(captured.closeLabel).toBeTypeOf("string");
  });

  it("preventDefaults Esc / outside handlers when dismissible=false", () => {
    render(
      <Modal title={ts("Locked")} open onClose={vi.fn()} dismissible={false}>
        <span>{CONTENT}</span>
      </Modal>,
    );

    const esc = makeEvent();
    captured.onEscapeKeyDown?.(esc);
    expect(esc.prevented).toBe(true);

    const pd = makeEvent();
    captured.onPointerDownOutside?.(pd);
    expect(pd.prevented).toBe(true);

    const io = makeEvent();
    captured.onInteractOutside?.(io);
    expect(io.prevented).toBe(true);

    // dismissible=false suppresses the built-in close button.
    expect(captured.closeLabel).toBeUndefined();
  });

  it("redirects open auto-focus to the panel itself", () => {
    render(
      <Modal title={ts("Focus")} open onClose={vi.fn()}>
        <span>{CONTENT}</span>
      </Modal>,
    );

    const panel = document.createElement("div");
    const focusSpy = vi.spyOn(panel, "focus");
    const evt = makeEvent() as ReturnType<typeof makeEvent> & {
      currentTarget: HTMLElement;
    };
    evt.currentTarget = panel;
    captured.onOpenAutoFocus?.(evt);

    expect(evt.prevented).toBe(true);
    expect(focusSpy).toHaveBeenCalled();
  });

  it("forwards the role prop (alertdialog) to Dialog.Content", () => {
    render(
      <Modal title={ts("Alert")} open onClose={vi.fn()} role="alertdialog">
        <span>{CONTENT}</span>
      </Modal>,
    );
    expect(captured.role).toBe("alertdialog");
  });
});


