  it("calls onSave with an empty string when submitting a blank field (preserve)", async () => {
    const onSave = vi.fn(async () => {});
    const user = userEvent.setup();
    render(
      <AiProviderCard
        providerKey={key({ configured: true })}
        displayName="Serper"
        brandColor="#5b6ef5"
        onSave={onSave}
