/**
 * Modal — behavior tests.
 *
 * Covers the branches that the branding compile-time test does NOT exercise:
 *  - open prop controls rendering
 *  - onClose fires when the Esc key is pressed (dismissible=true)
 *  - onClose does NOT fire when dismissible=false (Esc blocked)
 *  - children are rendered
 *  - footer is rendered when provided
 *  - eyebrow is rendered when provided
 *  - role prop override (alertdialog)
 *  - close button present when dismissible (closeLabel provided)
 *  - close button absent when non-dismissible
 *  - onPointerDownOutside / onInteractOutside handlers exercised via
 *    fireEvent on the document element (Radix DismissableLayer).
 */

import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, it, expect, vi } from "vitest";
import { Modal } from "../../src/components/Modal";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import type { TranslatedString } from "@omnicore-platform/platform-chrome";

// Cast through unknown so we don't have to produce a real TranslatedString
// brand in tests — Modal.brand.test.tsx covers the compile-time brand check.
function ts(s: string): TranslatedString {
  return s as unknown as TranslatedString;
}

// Child-node text routed through consts: react/jsx-no-literals (noStrings)
// forbids inline JSX string literals, so the rendered text the assertions
// query for is referenced as a variable rather than a bare literal.
const HIDDEN = "Hidden content";
const BODY = "Body content";
const CANCEL = "Cancel";
const CONTENT = "content";
const ARESURE = "Are you sure?";
const FOCUSME = "Focus me";

describe("Modal", () => {
  it("does not render content when open=false", () => {
    render(
      <Modal title={ts("My Modal")} open={false} onClose={vi.fn()}>
        <p>{HIDDEN}</p>
      </Modal>,
    );
    expect(screen.queryByRole("dialog")).toBeNull();
    expect(screen.queryByText("Hidden content")).toBeNull();
  });

  it("renders the dialog with its title when open=true", () => {
    render(
      <Modal title={ts("Create Workspace")} open onClose={vi.fn()}>
        <p>{BODY}</p>
      </Modal>,
    );
    expect(screen.getByRole("dialog", { name: /create workspace/i })).toBeInTheDocument();
    expect(screen.getByText("Body content")).toBeInTheDocument();
  });

  it("renders children inside the open dialog", () => {
    render(
      <Modal title={ts("Test Modal")} open onClose={vi.fn()}>
        <input placeholder="some field" />
      </Modal>,
    );
    expect(screen.getByPlaceholderText("some field")).toBeInTheDocument();
  });

  it("renders the footer when provided", () => {
    render(
      <Modal
        title={ts("With Footer")}
        open
        onClose={vi.fn()}
        footer={<button type="button">{CANCEL}</button>}
      >
        <span>{CONTENT}</span>
      </Modal>,
    );
    expect(screen.getByRole("button", { name: "Cancel" })).toBeInTheDocument();
  });

  it("does not render a footer container when footer is undefined", () => {
    const { container } = render(
      <Modal title={ts("No Footer")} open onClose={vi.fn()}>
        <span>{CONTENT}</span>
      </Modal>,
    );
    // The footer div has class containing justify-end — it should not be rendered.
    // Assert via the absence of Cancel-like buttons (no footer children).
    expect(screen.queryByRole("button", { name: "Cancel" })).toBeNull();
    void container; // suppress unused-variable lint
  });

  it("renders the eyebrow when provided", () => {
    render(
      <Modal
        title={ts("Main Title")}
        eyebrow={ts("New workspace")}
        open
        onClose={vi.fn()}
      >
        <span>{CONTENT}</span>
      </Modal>,
    );
    expect(screen.getByText("New workspace")).toBeInTheDocument();
  });

  it("does not render eyebrow span when eyebrow is undefined", () => {
    render(
      <Modal title={ts("No Eyebrow")} open onClose={vi.fn()}>
        <span>{CONTENT}</span>
      </Modal>,
    );
    // There should be no text outside the title for an eyebrow label.
    expect(screen.queryByText(/new workspace/i)).toBeNull();
  });

  it("applies alertdialog role when role='alertdialog'", () => {
    render(
      <Modal
        title={ts("Confirm Delete")}
        open
        onClose={vi.fn()}
        role="alertdialog"
      >
        <span>{ARESURE}</span>
      </Modal>,
    );
    expect(screen.getByRole("alertdialog")).toBeInTheDocument();
  });

  it("calls onClose when the built-in close button is clicked (dismissible=true)", async () => {
    const onClose = vi.fn();
    const user = userEvent.setup();
    render(
      <Modal title={ts("Dismissible")} open onClose={onClose}>
        <span>{CONTENT}</span>
      </Modal>,
    );
    // The close button uses the close-modal-aria label from messages
    const closeBtn = screen.getByRole("button", {
      name: m.common_close_modal_aria(),
    });
    await user.click(closeBtn);
    expect(onClose).toHaveBeenCalledTimes(1);
  });

  it("does NOT render the close button when dismissible=false", () => {
    render(
      <Modal title={ts("Non-dismissible")} open onClose={vi.fn()} dismissible={false}>
        <span>{CONTENT}</span>
      </Modal>,
    );
    expect(
      screen.queryByRole("button", { name: m.common_close_modal_aria() }),
    ).toBeNull();
  });

  it("calls onClose when the user presses Escape (dismissible=true)", async () => {
    const onClose = vi.fn();
    const user = userEvent.setup();
    render(
      <Modal title={ts("Esc Test")} open onClose={onClose}>
        <button type="button">{FOCUSME}</button>
      </Modal>,
    );
    // Focus something inside the dialog
    screen.getByRole("button", { name: "Focus me" }).focus();
    await user.keyboard("{Escape}");
    expect(onClose).toHaveBeenCalledTimes(1);
  });

  it("does NOT call onClose when Escape is pressed with dismissible=false", async () => {
    const onClose = vi.fn();
    const user = userEvent.setup();
    render(
      <Modal
        title={ts("Non-dismissible Esc")}
        open
        onClose={onClose}
        dismissible={false}
      >
        <button type="button">{FOCUSME}</button>
      </Modal>,
    );
    screen.getByRole("button", { name: "Focus me" }).focus();
    await user.keyboard("{Escape}");
    expect(onClose).not.toHaveBeenCalled();
  });


});



